/**
 * قاعدة البيانات البيداغوجية الرسمية لمادة اللغة العربية وآدابها - الطور الثانوي
 * مستخلصة ومفككة مباشرة من المناهج الرسمية لوزارة التربية الوطنية، التدرجات السنوية المحينة،
 * والبطاقات البيداغوجية المعتمدة رسمياً في التفتيش (نموذج مدرسة أشبال الأمة وعواع المدني بالمسيلة).
 */

export interface PedagogicalStepItem {
  stage: string;                  // وضعيّة التعلّم: وضعيّة الانطلاق / وضعيّة بناء التعلّمات / وضعيّة التّقييم
  objectiveDomain: string;        // الهدف التعلّمي: معرفيّ / مهاريّ / وجدانيّ
  teacherActivity: string;        // نشاط الأستاذ (متضمناً الاستراتيجية البيداغوجية صراحة)
  strategy?: string;              // الاستراتيجية البيداغوجية المعتمدة
  studentActivity: string;        // نشاط المتعلم
  evaluationType: string;         // التّقويم: تشخيصيّ / تكوينيّ / تحصيليّ
  indicatorsAndTiming: string;    // معايير ومؤشرات تحقق الإنجاز والزمن
}

export interface IntegrationTaskRow {
  section: string;                // المقطع: المقدّمة / العرض / الخاتمة
  resources: string;              // الموارد
  pattern: string;                // النّمط: سردي ووصفي / تفسيري وحجاجي...
  indicators: string;             // المؤشّر: 4 جمل / 2 جمل / 4 شعراء...
}

export interface EvaluationCriterionRow {
  criterion: string;              // المعيار: الملاءمة / أدوات المادة / الانسجام / جودة العرض
  checkMethod: string;            // طريقة التّحقّق
  remediation?: string;           // المعالجة البيداغوجية
}

export interface CurriculumLessonItem {
  id: string;
  grade: 'السنة الأولى' | 'السنة الثانية' | 'السنة الثالثة';
  stream: string;                 // 'شعب علمية مشتركة' | 'شعبة آداب وفلسفة' | 'لغات أجنبية' | 'جذع مشترك علوم' | 'جذع مشترك آداب' | 'جميع الشعب'
  unitNumber: number;
  unitTitle: string;
  unitDuration?: string;          // المدة الزمنية للوحدة (مثلاً: 06 ساعات)
  theme: string;                  // المحور الأدبي / البلاغي
  activity: 'أدب ونصوص' | 'قواعد اللغة' | 'بلاغة' | 'عروض' | 'مطالعة موجهة' | 'نص تواصلي' | 'تعبير كتابي' | 'وضعية إدماجية';
  topic: string;
  authorOrSource?: string;
  institution?: string;           // المؤسسة الرسمية (اختياري)
  competencyFinal: string;        // الكفاءة الختامية / المستهدفة
  competencyTarget?: string;
  objectivesList?: string[];      // الأهداف التعلمية التفصيلية
  indicators: string[];
  prerequisites: string;
  problemSituation: string;
  teacherActivity: string;
  studentActivity: string;
  method: string;
  tools: string;
  toolsNote?: string;
  evaluationDiag: string;
  evaluationFormative: string;
  evaluationFinal: string;
  remediation: string;
  enrichment: string;
  values: string;
  duration: string;
  supportPage?: string;
  // حقول خاصة بالجدول البيداغوجي المطور (وفق نموذج التفتيش)
  structuredSteps?: PedagogicalStepItem[];
  // حقول خاصة بالوضعية الإدماجية النقدية
  isIntegration?: boolean;
  writingTechniques?: string;
  rhetoricResources?: string;
  linguisticResources?: string;
  intellectualResources?: string;
  integrationTasks?: IntegrationTaskRow[];
  rubricCriteria?: EvaluationCriterionRow[];
}

